#nullable enable // autogenerated

using System;
using MVZ2Logic.Models.Elements;
using UnityEngine;

namespace MVZ2.GameContent.Models
{
    [ExecuteAlways]
    public class NightmareSkyAnimator : MonoBehaviour
    {
        private void Update()
        {
            if (!sky)
                return;
            sky.SetFloat("_WarpTime", warpTime);
            sky.ApplyShaderProperties();
        }
        [SerializeField]
        private RendererElement sky = null!;
        [Range(0, 1)]
        [SerializeField]
        private float warpTime;
    }
}
